        std.mem.eql(u8, name, "vkGetPhysicalDeviceProperties2KHR") or
        std.mem.eql(u8, name, "vkGetPhysicalDeviceFormatProperties2KHR") or
        std.mem.eql(u8, name, "vkGetPhysicalDeviceImageFormatProperties2KHR") or
