    lock_icd();
    defer unlock_icd();
    const output_raw = output_address orelse return c.VK_ERROR_INITIALIZATION_FAILED;
    if (@intFromPtr(output_raw) % @alignOf(c.VkDevice) != 0) return c.VK_ERROR_INITIALIZATION_FAILED;
