        error.OutOfMemory => c.VK_ERROR_OUT_OF_HOST_MEMORY,
        error.Backend => extension_backend_result,
        error.Lost => c.VK_ERROR_DEVICE_LOST,
        else => c.VK_ERROR_INITIALIZATION_FAILED,
