        const bytes=@as([*]u8,@ptrCast(output.?))[0..capacity];
        if(opcode==85) {
            std.mem.writeInt(u64,bytes[8..16],1,.little);
            std.mem.writeInt(u64,bytes[16..24],fixture.base.id,.little);
